+      run(
+        "pnpm",
+        [
+          "exec",
+          "wrangler",
+          "deploy",
+          "--config",
+          outputPaths[kind],
+          "--dry-run",
+          "--strict",
+          "--outdir",
+          resolve(outputDirectory, kind, "bundle"),
+        ],
+        {
+          cwd: worker.directory,
+          env: {
+            ...process.env,
+            NODE_OPTIONS: [process.env.NODE_OPTIONS, "--conditions=development"]
+              .filter(Boolean)
+              .join(" "),
+          },
+          failureMessage: `${worker.name} config dry-run failed`,
