+    return await Promise.race([
+      callback,
+      new Promise((_, reject) => {
+        timeout = timers.setTimeout(
+          () =>
+            reject(
+              new Error(`OAuth browser flow timed out after ${timeoutMilliseconds} ms`),
+            ),
+          timeoutMilliseconds,
+        );
+      }),
+    ]);
+  } finally {
+    if (timeout !== undefined) timers.clearTimeout(timeout);
+  }
