+    const timeoutHandle = Symbol("timeout");
+    let scheduledFor;
+    let clearedHandle;
+    const timers = {
+      setTimeout(_callback, milliseconds) {
+        scheduledFor = milliseconds;
+        return timeoutHandle;
+      },
+      clearTimeout(handle) {
+        clearedHandle = handle;
+      },
