+     OR serialized ~* '(bearer[[:space:]]+[A-Z0-9._~+/-]+=*|spk_[A-Z0-9_-]{12,})' THEN
+    RAISE EXCEPTION 'audit metadata contains a prohibited sensitive value'
+      USING ERRCODE = '23514',
+            CONSTRAINT = 'audit_events_sensitive_metadata';
+  END IF;
+  RETURN NEW;
+END;
+$$;

